bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
echo VIDEO_LIVE_RUNNING=PASS
docker exec "$cid" node --input-type=module -e '
import {readFileSync} from "node:fs";
for(const [tag,p] of [["OWNER","/opt/videobot/owner/gateOwner.mjs"],["WIRING","/opt/videobot/src/telegram/creatorWiring.mjs"]]){
 const s=readFileSync(p,"utf8");
 console.log(tag+"_FILE_PRESENT=YES");
 if(tag==="OWNER"){
  console.log("VIDEO_TOPIC_CONFIG_IMPLEMENTED="+s.includes("configuredVideoSaleTopic"));
  console.log("VIDEO_RELEASE_ALLOWANCE_IMPLEMENTED="+/verifyRelease[\\s\\S]{0,450}video_sale/.test(s));
  console.log("VIDEO_THREAD_ENV_PRESENT="+Boolean(process.env.VIDEOBOT_VIDEO_SALE_THREAD_ID));
  console.log("VIDEO_TITLE_ENV_PRESENT="+Boolean(process.env.VIDEOBOT_VIDEO_SALE_TOPIC_TITLE));
 }else console.log("VIDEO_PUBLISH_WIRED="+s.includes("publishVideoListing"));
}
'
echo VIDEO_DIAG_COMPLETE=YES
